/* ══════════════════════════════════════════════════════════
   PureWrite export module — PDF (via vendored jsPDF) and a
   hand-rolled minimal DOCX (ZIP + OOXML) writer. Both consume the
   same `model` object built by buildEssayModel() in purewrite.html,
   so the two formats can never disagree about paragraph breaks.

   Everything here runs fully offline: jsPDF is vendored in
   vendor/jspdf.umd.min.js, the embedded font below is vendored, and
   the DOCX writer has no external dependency at all.
   ══════════════════════════════════════════════════════════ */

/* Liberation Serif Regular, subset to Basic Latin + Latin-1 Supplement +
   Latin Extended-A + the four Vietnamese-specific letters (Ơ ơ Ư ư) +
   Latin Extended Additional (Vietnamese tone marks) + em/en dash, curly
   quotes, and ellipsis. Same subsetting approach and range list as the
   ToolshedSans font embedded in seating-chart-maker.html (see
   FONT-LICENSE.md), applied to a serif face since MLA requires one.
   Liberation Serif is the SIL OFL-licensed, metrically-compatible
   substitute for Times New Roman — see vendor/liberation-serif-LICENSE.txt.
   Characters outside this subset (CJK, Arabic, Thai, etc.) will not
   render in the PDF; PW_FONT_COVERAGE below is checked before export so
   a student who needs one of those scripts is steered to the Word
   download instead, which has no such limit — it stores literal text,
   not drawn glyphs. */
const PW_FONT_B64 = "";

const PW_FONT_RANGES = [
  [0x0020, 0x007E], [0x00A0, 0x00FF], [0x0100, 0x017F],
  [0x01A0, 0x01A1], [0x01AF, 0x01B0], [0x1E00, 0x1EFF],
  [0x2013, 0x2014], [0x2018, 0x2019], [0x201C, 0x201D], [0x2026, 0x2026]
];
function charInFontCoverage(code) {
  return PW_FONT_RANGES.some(([lo, hi]) => code >= lo && code <= hi);
}
function findUncoveredChars(text) {
  const missing = new Set();
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (!charInFontCoverage(code)) missing.add(ch);
  }
  return [...missing];
}

function registerPdfFont(doc) {
  doc.addFileToVFS('PureWriteSerif.ttf', PW_FONT_B64);
  doc.addFont('PureWriteSerif.ttf', 'PWSerif', 'normal');
  return 'PWSerif';
}

/* ══════════════════════════════════════════════════════════
   PDF EXPORT
   ══════════════════════════════════════════════════════════ */
function downloadPdf(model) {
  const fullText = model.paragraphs.join(' ');
  const missing = findUncoveredChars(fullText);
  if (missing.length) {
    showToast('Some characters (' + missing.slice(0, 6).join(' ') + ') can\'t be drawn in the PDF font — try Download Word instead for full accuracy.', 6000);
  }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'in', format: 'letter' });
  const FONT = registerPdfFont(doc);
  const FONT_SIZE = 12;
  doc.setFont(FONT, 'normal');
  doc.setFontSize(FONT_SIZE);

  const pageW = 8.5, pageH = 11;
  const margin = 1;
  const contentW = pageW - margin * 2;
  const lineHeight = (FONT_SIZE * 2) / 72; // MLA double-spacing: 2x the font's point size
  const indent = 0.5;
  let y = margin;
  let pageNum = 1;

  function drawHeader() {
    doc.setFont(FONT, 'normal');
    doc.setFontSize(FONT_SIZE);
    doc.text(`${model.lastName} ${pageNum}`, pageW - margin, 0.5, { align: 'right' });
  }
  function ensureRoom() {
    if (y + lineHeight > pageH - margin) {
      doc.addPage();
      pageNum++;
      drawHeader();
      y = margin;
    }
  }
  function drawLine(text, x, opts) {
    ensureRoom();
    doc.text(text, x, y, opts);
    y += lineHeight;
  }

  drawHeader();

  [model.studentName, model.teacherName, model.className, model.dateStr]
    .filter(Boolean)
    .forEach(line => drawLine(line, margin));

  drawLine(model.title, pageW / 2, { align: 'center' });

  model.paragraphs.forEach(para => {
    const firstLineWrap = doc.splitTextToSize(para, contentW - indent);
    const firstLine = firstLineWrap[0] || '';
    const firstLineWordCount = firstLine.trim().length ? firstLine.trim().split(/\s+/).length : 0;
    const allWords = para.trim().split(/\s+/);
    const restWords = allWords.slice(firstLineWordCount);
    const restText = restWords.join(' ');
    const restLines = restText ? doc.splitTextToSize(restText, contentW) : [];

    drawLine(firstLine, margin + indent);
    restLines.forEach(line => drawLine(line, margin));
  });

  doc.save(buildFilename('pdf'));
}

/* ══════════════════════════════════════════════════════════
   MINIMAL ZIP WRITER (STORE method — no compression needed for a
   single essay's worth of XML; avoids an entire class of deflate
   correctness risk for negligible size cost)
   ══════════════════════════════════════════════════════════ */
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(bytes) {
  let c = 0xFFFFFFFF;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}

function dosDateTime(d) {
  const time = ((d.getHours() & 0x1F) << 11) | ((d.getMinutes() & 0x3F) << 5) | ((d.getSeconds() >> 1) & 0x1F);
  const date = (((d.getFullYear() - 1980) & 0x7F) << 9) | (((d.getMonth() + 1) & 0xF) << 5) | (d.getDate() & 0x1F);
  return { time, date };
}

function makeZip(files) {
  // files: [{ name: 'word/document.xml', text: '...' }, ...]
  const enc = new TextEncoder();
  const { time, date } = dosDateTime(new Date());
  const localParts = [];
  const centralParts = [];
  let offset = 0;

  files.forEach(f => {
    const nameBytes = enc.encode(f.name);
    const dataBytes = enc.encode(f.text);
    const crc = crc32(dataBytes);

    const local = new DataView(new ArrayBuffer(30));
    local.setUint32(0, 0x04034b50, true);
    local.setUint16(4, 20, true);        // version needed
    local.setUint16(6, 0, true);         // flags
    local.setUint16(8, 0, true);         // method: store
    local.setUint16(10, time, true);
    local.setUint16(12, date, true);
    local.setUint32(14, crc, true);
    local.setUint32(18, dataBytes.length, true); // compressed size
    local.setUint32(22, dataBytes.length, true); // uncompressed size
    local.setUint16(26, nameBytes.length, true);
    local.setUint16(28, 0, true);        // extra field length
    localParts.push(new Uint8Array(local.buffer), nameBytes, dataBytes);

    const central = new DataView(new ArrayBuffer(46));
    central.setUint32(0, 0x02014b50, true);
    central.setUint16(4, 20, true);      // version made by
    central.setUint16(6, 20, true);      // version needed
    central.setUint16(8, 0, true);
    central.setUint16(10, 0, true);
    central.setUint16(12, time, true);
    central.setUint16(14, date, true);
    central.setUint32(16, crc, true);
    central.setUint32(20, dataBytes.length, true);
    central.setUint32(24, dataBytes.length, true);
    central.setUint16(28, nameBytes.length, true);
    central.setUint16(30, 0, true);      // extra length
    central.setUint16(32, 0, true);      // comment length
    central.setUint16(34, 0, true);      // disk number
    central.setUint16(36, 0, true);      // internal attrs
    central.setUint32(38, 0, true);      // external attrs
    central.setUint32(42, offset, true); // offset of local header
    centralParts.push(new Uint8Array(central.buffer), nameBytes);

    offset += 30 + nameBytes.length + dataBytes.length;
  });

  const centralStart = offset;
  let centralSize = 0;
  centralParts.forEach(p => centralSize += p.length);

  const eocd = new DataView(new ArrayBuffer(22));
  eocd.setUint32(0, 0x06054b50, true);
  eocd.setUint16(4, 0, true);
  eocd.setUint16(6, 0, true);
  eocd.setUint16(8, files.length, true);
  eocd.setUint16(10, files.length, true);
  eocd.setUint32(12, centralSize, true);
  eocd.setUint32(16, centralStart, true);
  eocd.setUint16(20, 0, true);

  const all = [...localParts, ...centralParts, new Uint8Array(eocd.buffer)];
  const total = all.reduce((sum, p) => sum + p.length, 0);
  const out = new Uint8Array(total);
  let pos = 0;
  all.forEach(p => { out.set(p, pos); pos += p.length; });
  return out;
}

/* ══════════════════════════════════════════════════════════
   MINIMAL DOCX (OOXML) WRITER
   ══════════════════════════════════════════════════════════ */
function xmlEscape(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}
function wRun(text) {
  return `<w:r><w:t xml:space="preserve">${xmlEscape(text)}</w:t></w:r>`;
}

function buildContentTypesXml() {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
<Override PartName="/word/header1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/>
</Types>`;
}
function buildPackageRelsXml() {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>`;
}
function buildDocumentRelsXml() {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header1.xml"/>
</Relationships>`;
}
function buildStylesXml() {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
<w:docDefaults>
<w:rPrDefault><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/><w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr></w:rPrDefault>
<w:pPrDefault><w:pPr><w:spacing w:before="0" w:after="0" w:line="480" w:lineRule="auto"/></w:pPr></w:pPrDefault>
</w:docDefaults>
<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:qFormat/></w:style>
<w:style w:type="paragraph" w:styleId="Header"><w:name w:val="header"/><w:basedOn w:val="Normal"/><w:pPr><w:spacing w:line="240" w:lineRule="auto"/></w:pPr></w:style>
</w:styles>`;
}
function buildHeaderXml(model) {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:hdr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
<w:p>
<w:pPr><w:pStyle w:val="Header"/><w:jc w:val="right"/></w:pPr>
${wRun(model.lastName + ' ')}
<w:r><w:fldChar w:fldCharType="begin"/></w:r>
<w:r><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r>
<w:r><w:fldChar w:fldCharType="separate"/></w:r>
<w:r><w:t>1</w:t></w:r>
<w:r><w:fldChar w:fldCharType="end"/></w:r>
</w:p>
</w:hdr>`;
}
function buildDocumentXml(model) {
  const headingLines = [model.studentName, model.teacherName, model.className, model.dateStr]
    .filter(Boolean)
    .map(line => `<w:p>${wRun(line)}</w:p>`)
    .join('\n');

  const titlePara = `<w:p><w:pPr><w:jc w:val="center"/></w:pPr>${wRun(model.title)}</w:p>`;

  const bodyParas = model.paragraphs.map(p =>
    `<w:p><w:pPr><w:ind w:firstLine="720"/></w:pPr>${wRun(p)}</w:p>`
  ).join('\n');

  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<w:body>
${headingLines}
${titlePara}
${bodyParas}
<w:sectPr>
<w:headerReference w:type="default" r:id="rId2"/>
<w:pgSz w:w="12240" w:h="15840"/>
<w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/>
</w:sectPr>
</w:body>
</w:document>`;
}

function downloadDocx(model) {
  const files = [
    { name: '[Content_Types].xml', text: buildContentTypesXml() },
    { name: '_rels/.rels', text: buildPackageRelsXml() },
    { name: 'word/document.xml', text: buildDocumentXml(model) },
    { name: 'word/_rels/document.xml.rels', text: buildDocumentRelsXml() },
    { name: 'word/styles.xml', text: buildStylesXml() },
    { name: 'word/header1.xml', text: buildHeaderXml(model) }
  ];
  const zipBytes = makeZip(files);
  const blob = new Blob([zipBytes], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = buildFilename('docx');
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
